Here is the commit message:
thermal: core: Fix thermal zone governor cleanup issues

If thermal_zone_device_register_with_trips() fails after adding
a thermal governor to the thermal zone being registered, the
governor is not removed from it as appropriate which may lead to
a memory leak.

In turn, thermal_zone_device_unregister() calls thermal_set_governor()
without acquiring the thermal zone lock beforehand which may race with
a governor update via sysfs and may lead to a use-after-free in that
case.

Address these issues by adding two thermal_set_governor() calls, one to
thermal_release() to remove the governor from the given thermal zone,
and one to the thermal zone registration error path to cover failures
preceding the thermal zone device registration.

Fixes: e33df1d2f3a0 ("thermal: let governors have private data for each thermal zone")
Cc: All applicable <stable@vger.kernel.org>
Signed-off-by: Rafael J. Wysocki <rafael.j.wysocki@intel.com>
Link: https://patch.msgid.link/5092923.31r3eYUQgx@rafael.j.wysocki

Here is the root cause:
(1) When `thermal_zone_device_register_with_trips()` fails after adding a governor to the thermal zone (e.g., when creating device groups fails), the governor is not removed, leading to a memory leak. (2) In `thermal_zone_device_unregister()`, `thermal_set_governor(tz, NULL)` is called without holding the thermal zone lock, which can race with a concurrent governor update via sysfs, causing a use-after-free. The proper fix is to defer governor cleanup to `thermal_release()` (which occurs after the last reference is dropped) and to add cleanup in the registration error path.

Here is the patch:

 static void thermal_release(struct device *dev)
 {
 	struct thermal_zone_device *tz;
 	struct thermal_cooling_device *cdev;

 	if (!strncmp(dev_name(dev), "thermal_zone",
 		     sizeof("thermal_zone") - 1)) {
 		tz = to_thermal_zone(dev);
 		thermal_zone_destroy_device_groups(tz);
+		thermal_set_governor(tz, NULL);
 		mutex_destroy(&tz->lock);
 		complete(&tz->removal);
 	} else if (!strncmp(dev_name(dev), "cooling_device",
 			    sizeof("cooling_device") - 1)) {
 		cdev = to_cooling_device(dev);
 		thermal_cooling_device_destroy_sysfs(cdev);
 		kfree_const(cdev->type);
 		ida_free(&thermal_cdev_ida, cdev->id);
 		kfree(cdev);
 	}
 }

  */
 struct thermal_zone_device *
 thermal_zone_device_register_with_trips(const char *type,
 					const struct thermal_trip *trips,
 					int num_trips, void *devdata,
 					const struct thermal_zone_device_ops *ops,
 					const struct thermal_zone_params *tzp,
 					unsigned int passive_delay,
 					unsigned int polling_delay)
 {
 	const struct thermal_trip *trip = trips;
 	struct thermal_zone_device *tz;
 	struct thermal_trip_desc *td;
 	size_t type_len = 0;
 	int id;
 	int result;

 	if (type)
 		type_len = strnlen(type, THERMAL_NAME_LENGTH);

 	if (type_len == 0) {
 		pr_err("No thermal zone type defined\n");
 		return ERR_PTR(-EINVAL);
 	}

 	if (type_len == THERMAL_NAME_LENGTH) {
 		pr_err("Thermal zone name (%s) too long, should be under %d chars\n",
 		       type, THERMAL_NAME_LENGTH);
 		return ERR_PTR(-EINVAL);
 	}

 	if (num_trips < 0) {
 		pr_err("Incorrect number of thermal trips\n");
 		return ERR_PTR(-EINVAL);
 	}

 	if (!ops || !ops->get_temp) {
 		pr_err("Thermal zone device ops not defined or invalid\n");
 		return ERR_PTR(-EINVAL);
 	}

 	if (num_trips > 0 && !trips)
 		return ERR_PTR(-EINVAL);

 	if (polling_delay && passive_delay > polling_delay)
 		return ERR_PTR(-EINVAL);

 	if (!thermal_class)
 		return ERR_PTR(-ENODEV);

 	tz = kzalloc_flex(*tz, trips, num_trips);
 	if (!tz)
 		return ERR_PTR(-ENOMEM);

 	if (tzp) {
 		tz->tzp = kmemdup(tzp, sizeof(*tzp), GFP_KERNEL);
 		if (!tz->tzp) {
 			result = -ENOMEM;
 			goto free_tz;
 		}
 	}

 	INIT_LIST_HEAD(&tz->node);
 	INIT_LIST_HEAD(&tz->trips_high);
 	INIT_LIST_HEAD(&tz->trips_reached);
 	INIT_LIST_HEAD(&tz->trips_invalid);
 	ida_init(&tz->ida);
 	mutex_init(&tz->lock);
 	init_completion(&tz->removal);
 	init_completion(&tz->resume);
 	id = ida_alloc(&thermal_tz_ida, GFP_KERNEL);
 	if (id < 0) {
 		result = id;
 		goto free_tzp;
 	}

 	tz->id = id;
 	strscpy(tz->type, type, sizeof(tz->type));

 	tz->ops = *ops;
 	if (!tz->ops.critical)
 		tz->ops.critical = thermal_zone_device_critical;

 	tz->device.class = thermal_class;
 	tz->devdata = devdata;
 	tz->num_trips = num_trips;
 	for_each_trip_desc(tz, td) {
 		td->trip = *trip++;
 		INIT_LIST_HEAD(&td->thermal_instances);
 		INIT_LIST_HEAD(&td->list_node);
 		/*
 		 * Mark all thresholds as invalid to start with even though
 		 * this only matters for the trips that start as invalid and
 		 * become valid later.
 		 */
 		move_to_trips_invalid(tz, td);
 	}

 	tz->polling_delay_jiffies = msecs_to_jiffies(polling_delay);
 	tz->passive_delay_jiffies = msecs_to_jiffies(passive_delay);
 	tz->recheck_delay_jiffies = THERMAL_RECHECK_DELAY;

 	tz->state = TZ_STATE_FLAG_INIT;

 	result = dev_set_name(&tz->device, "thermal_zone%d", tz->id);
 	if (result)
 		goto remove_id;

 	thermal_zone_device_init(tz);

 	result = thermal_zone_init_governor(tz);
 	if (result)
 		goto remove_id;

 	/* sys I/F */
 	/* Add nodes that are always present via .groups */
 	result = thermal_zone_create_device_groups(tz);
-	if (result)
+	if (result) {
+		thermal_set_governor(tz, NULL);
 		goto remove_id;
+	}

 	result = device_register(&tz->device);
 	if (result)
 		goto release_device;

 	if (!tz->tzp || !tz->tzp->no_hwmon) {
 		result = thermal_add_hwmon_sysfs(tz);
 		if (result)
 			goto unregister;
 	}

 	result = thermal_thresholds_init(tz);
 	if (result)
 		goto remove_hwmon;

 	thermal_zone_init_complete(tz);

 	thermal_notify_tz_create(tz);

 	thermal_debug_tz_add(tz);

 	return tz;

 remove_hwmon:
 	thermal_remove_hwmon_sysfs(tz);
 unregister:
 	device_del(&tz->device);
 release_device:
 	put_device(&tz->device);
 	wait_for_completion(&tz->removal);
 remove_id:
 	ida_free(&thermal_tz_ida, id);
 free_tzp:
 	kfree(tz->tzp);
 free_tz:
 	kfree(tz);
 	return ERR_PTR(result);
 }
 EXPORT_SYMBOL_GPL(thermal_zone_device_register_with_trips);
  */
 void thermal_zone_device_unregister(struct thermal_zone_device *tz)
 {
 	if (!tz)
 		return;

 	thermal_debug_tz_remove(tz);

 	if (!thermal_zone_exit(tz))
 		return;

 	cancel_delayed_work_sync(&tz->poll_queue);

-	thermal_set_governor(tz, NULL);
-
 	thermal_thresholds_exit(tz);
 	thermal_remove_hwmon_sysfs(tz);
 	ida_free(&thermal_tz_ida, tz->id);
 	ida_destroy(&tz->ida);

 	device_del(&tz->device);
 	put_device(&tz->device);

 	thermal_notify_tz_delete(tz);

 	wait_for_completion(&tz->removal);
 	kfree(tz->tzp);
 	kfree(tz);
 }
 EXPORT_SYMBOL_GPL(thermal_zone_device_unregister);


